(function() {
  var _result = {};
  try {
    var comp = app.project.activeItem;
    if (!comp || !(comp instanceof CompItem)) {
      _result = {status:"error", message:"No active comp"};
      return JSON.stringify(_result);
    }
    var p = {lutPath: ${lutPath}, intensity: ${intensity}, lutFormat: ${lutFormat}};
    var layer = comp.layer(1);
    if (!layer) { _result = {status:"error", message:"No layer found"}; return JSON.stringify(_result); }
    var lumetri = layer.Effects.addProperty("ADBE Lumetri Color");
    var lutApplied = false;
    try {
      var inputLutProp = lumetri.property("Input LUT");
      if (inputLutProp) { inputLutProp.setValue(p.lutPath); lutApplied = true; }
    } catch(e1) {
      try { lumetri.property(1).setValue(p.lutPath); lutApplied = true; } catch(e2) {}
    }
    if (p.intensity < 1) { layer.property("Opacity").setValue(p.intensity * 100); }
    _result = {status:"success", message:"LUT applied: kodak_2383", lutPath: p.lutPath, intensity: p.intensity, format: p.lutFormat, lutApplied: lutApplied};
  } catch(e) {
    _result = {status:"error", message:"Error: " + e.toString()};
  }
  return JSON.stringify(_result);
})();

