      if (inputLutProp) { inputLutProp.setValue(p.lutPath); lutApplied = true; }
    } catch(e1) {
      try { lumetri.property(1).setValue(p.lutPath); lutApplied = true; } catch(e2) {}
    }
    if (p.intensity < 1) { layer.property("Opacity").setValue(p.intensity * 100); }
    _result = {status:"success", message:"LUT applied: landscape_lut", lutPath: p.lutPath, intensity: p.intensity, format: p.lutFormat, lutApplied: lutApplied};
  } catch(e) {
    _result = {status:"error", message:"Error: " + e.toString()};
  }
  return JSON.stringify(_result);
})();
